#!/bin/sh
# v4 배치1 재생성(QA 실패분, 영웅별 추가 지시). 실행(프로젝트 루트): sh docker/gemini/hero_v4_batch1.sh
G="sh docker/gemini/hero_v4_gen.sh"
$G julius_caesar --force "--note=v4b1: 후면 walk2 검 누락·측면 idle 3/4·흉갑 어두움" "--extra=글라디우스는 오른손에 들고 9칸 모두 보이게(뒷모습 3칸 모두 칼이 같은 위치·같은 각도로 몸 오른쪽 아래에 보임). 측면 행 가운데 칸도 완전한 왼쪽 옆모습. 흉갑은 초상화처럼 밝은 청동(금갈색)으로 크게, 망토는 짙은 적갈색, 튜닉 소매 붉은색, 월계관은 9칸 모두 녹색으로 뚜렷하게"
$G oda_nobunaga --force "--note=v4b1: 측면 walk2·후면 walk1 창 위치 바뀜" "--extra=창은 9칸 모두 같은 손에 세로로 들고, 정면 3칸은 창이 모두 화면 왼쪽, 측면 3칸은 창이 모두 몸 앞(화면 왼쪽), 뒷모습 3칸은 창이 모두 화면 오른쪽. 측면 가운데 칸도 완전한 왼쪽 옆모습"
$G charles_martel --force "--note=v4b1: 측면 walk2 창 누락" "--extra=측면 행 세 칸 모두 세로로 세운 창과 원형 방패가 보인다(walk2 칸에도 창 필수). 9칸 모두 창 1개·방패 1개"
$G leonidas --force "--note=v4b1: 측면 행 창 누락" "--extra=측면 행 세 칸 모두 세로로 세운 긴 창이 보인다(창대가 방패 위아래로 길게 보임). 9칸 모두 창 1개·둥근 청동 방패 1개, 붉은 투구 깃 장식 9칸 동일"
$G mehmed_ii --force "--note=v4b1: 칼이 일부 칸에만 보임" "--extra=허리 왼쪽에 찬 휜 칼(칼집·금 칼자루)이 9칸 모두 같은 위치에 보인다. 손에 칼을 빼 들지 않는다. 터번 앞 금 깃털 장식 9칸 동일"
$G gustavus_adolphus --force "--note=v4b1: 은색 흉갑·레이스 깃 안 보임" "--extra=기수의 몸통은 초상화처럼 금 테두리의 밝은 은색 강철 흉갑이 크게 보이고(갈색 코트로 가리지 않음), 목에 큰 흰 레이스 깃, 소매는 갈색 가죽, 어깨에 짙은 파란 망토. 금발·콧수염. 뒷모습 3칸은 말 엉덩이와 꼬리까지 칸 안에"
$G nelson --force "--note=v4b1: 후면 walk2·측면 walk2 칼 누락/각도 다름" "--extra=사브르는 오른손에 들고 9칸 모두 같은 각도(칼끝이 아래 바깥쪽)로 보인다. 뒷모습 3칸 모두 칼이 보이고, 측면 3칸 모두 칼 각도 같음"
